{
  "title": "把承诺、观察和结论分开：铁路材料评价",
  "goal": "能区分A的广告承诺与B的日记观察，分别检验“成本已经减半”和“所有人都受益”，并写出与证据强度相符、范围有限的评价。",
  "steps": [
    {
      "title": "先看是谁在说",
      "explanation": "你这次回答注意到了A出现“成本减半”、B出现“货运快了”，这是有用的起点。但评价史料要先问来源：A是1840年铁路公司的广告，广告要招商、争取支持，可能带有宣传目的；B是1842年本地商人的日记，是个人观察，能看到的时间和地点都有限。两者不是同一种证据。",
      "question": "请分别写：A是谁发布的、可能想达到什么目的？B是谁记录的、记录范围可能有多大？",
      "checkpoint": "能说出A是铁路公司广告或宣传材料，目的包括招揽生意、塑造形象等；B是本地商人的个人日记，只代表其见闻和局部范围。"
    },
    {
      "title": "把“承诺”和“已发生”分开",
      "explanation": "A中“开通后货运成本减半，人人受益”说的是将来会怎样，属于承诺或预期，不能因为写在广告里就当作已经发生的事实。B中“货运快了”是对已经发生变化的观察。判断一句话是不是事实，要看它说的是“将怎样”还是“已经看到怎样”。",
      "question": "在A中找出一个表示未来或承诺的词语；在B中找出一个表示已经观察到的变化的短语。",
      "checkpoint": "能指出“开通后”（或“承诺”）与“货运快了”；能说明前者是预期，后者是观察。"
    },
    {
      "title": "把大结论拆成两个小结论",
      "explanation": "原结论包含两件事：①成本已经减半；②所有人都受益。它们需要不同证据，不能用一个“货运快了”一起证明。先拆开，才能逐项核对。",
      "question": "分别写出：要证明“成本已经减半”，需要什么数据？要证明“所有人都受益”，需要哪些人的情况？",
      "checkpoint": "前者需要开通前后的实际运价、收费或账单等；后者需要不同群体（至少包括本地车夫等）的收入或受益情况，不能只看一个商人。"
    },
    {
      "title": "读B时盯住转折和受影响的人",
      "explanation": "读日记要注意“但”后面的限制，以及被提到收入变化的人。B不只说速度，还说到收费和本地车夫。局部观察不一定支持“人人受益”。",
      "question": "B中哪些信息会限制“成本已经减半”？哪些信息会与“所有人都受益”冲突？请引用原材料中的词语回答。",
      "checkpoint": "能找到“新收费仍高”限制“成本减半”；能找到“本地车夫收入减少”与“人人受益”冲突。"
    },
    {
      "title": "“互相印证”要看是否说的是同一件事",
      "explanation": "两份材料都提到铁路或货运，不等于它们印证同一个结论。A说的是承诺中的成本，B观察到的是速度变快；速度变快不能自动推出成本减半。要让二者互相印证，必须找到它们对同一个可测事实的一致记录。",
      "question": "“B说货运快了”能不能直接证明“成本减半”？如果不能，中间还缺什么证据？",
      "checkpoint": "能明确说不能；指出缺少实际收费或运价的前后对比，速度和成本不是同一个指标。"
    },
    {
      "title": "给结论加上范围",
      "explanation": "B只是本地商人的日记，不是对所有地区、所有群体的统计。由一则局部观察推广到“所有人”，范围扩大了。评价时可以用“材料显示……”“不能确定……”“有材料反映……”来标明证据强度。",
      "question": "如果只用B，能不能说“所有本地人都受损”或“所有人都受益”？请说明理由。",
      "checkpoint": "能说不能；B只反映商人所见，尤其提到车夫，但不足以代表所有人，需要更多群体材料。"
    },
    {
      "title": "写出有限度的评价",
      "explanation": "现在把前面几步合起来：先分来源，再分承诺或观察，再逐项判断，最后用有范围的句子表达。不要写“确定事实”，要写清楚哪一点有支持、哪一点不能确定、哪一点有反证。",
      "question": "请用“可以确定……；不能确定……；因为有……”的句式，写一句对原结论的评价，并保留至少一个范围限制。",
      "checkpoint": "句子能区分A的承诺与B的观察；不把成本减半和人人受益都说成确定事实；提到B中至少一个限制或反证。"
    }
  ],
  "parent_tips": [
    "先让孩子圈出A、B各自是谁说的、为什么说，不要急着判断结论对错。",
    "孩子说“互相印证”时，追问：两则材料印证的是同一个指标吗？一个是承诺，一个是观察吗？",
    "听到“所有人”“确定事实”这类词，就请孩子指出材料覆盖了哪些人、还有谁没有出现。",
    "让孩子引用原材料中的词语作依据，例如“新收费仍高”“车夫收入减少”，不要替孩子补结论。",
    "孩子答完后，先肯定他找对的具体词句，再只针对一个卡点继续追问。"
  ],
  "understanding_checks": [
    "一则招生广告写“报名后成绩一定提高”，一位同学日记写“课程有趣，但我这次测验没进步”。这则日记能否证明广告的承诺已经实现？请说明理由。",
    "要判断“新公交让所有居民都受益”，除了公交公司的宣传单，你至少还要收集哪两类材料？为什么？"
  ],
  "practice": [
    {
      "id": "tram-claim",
      "prompt": "虚构材料：1900年某镇电车公司的宣传单写道：“电车开通后，所有居民出行时间将减少一半，人人受益。”1902年一位本地记者报道：“电车确实开得很快，但票价仍然很高；几名拉车工人说，电车开通后他们的收入减少了。”请完成三项：①指出哪句是公司承诺、哪句是记者观察；②分别判断“出行时间减少一半”和“所有居民都受益”是否已得到材料支持；③写一句有限度的评价。",
      "purpose": "练习区分宣传承诺与观察记录，并逐项检验结论、识别反证和范围限制。",
      "hints": [
        "先看宣传单是谁发的，它希望读者相信什么。",
        "“将减少一半”与“电车确实开得很快”是一回事吗？",
        "注意“但”后面的票价和拉车工人收入。"
      ],
      "success_criteria": [
        "能指出宣传单中的“将减少一半、人人受益”是公司承诺，不是已经发生的事实。",
        "能指出记者报道中的“电车确实开得很快”是观察，而“票价仍然很高”“拉车工人收入减少”构成限制或反证。",
        "能说明“出行时间减少一半”没有被材料直接证实，需要开通前后的实际用时记录；“所有居民都受益”与拉车工人收入减少冲突，也不能由一则报道代表所有居民。",
        "评价句能区分承诺与观察，不把两个结论都说成确定事实，并保留范围限制。"
      ]
    },
    {
      "id": "evidence-choice",
      "prompt": "某镇想检验铁路公司广告所说“货运成本已经减半”是否属实。现有三份材料：甲，铁路公司第二年再次刊登同样广告；乙，居民保存的开通前后货运收费单和日期记录；丙，一篇以铁路为背景的小说，说运费很便宜。哪一份最能直接检验该说法？请说明理由，并指出另外两份为什么较弱。",
      "purpose": "练习选择能直接检验结论的证据，识别重复宣传和虚构材料不能当作实际收费记录。",
      "hints": [
        "问一问：哪份材料记录了实际收了多少钱？",
        "广告重复一次，会不会产生新的收费事实？",
        "小说中的说法能当作收费凭证吗？"
      ],
      "success_criteria": [
        "选择乙。",
        "能说明乙是开通前后的实际收费单和日期记录，可以直接比较成本是否变化。",
        "能说明甲只是重复公司承诺，不是独立观察或实际收费记录；丙是小说，不能作为实际运价的证据。"
      ]
    }
  ],
  "recap": "材料评价先看“谁在说、为什么说”；再把广告承诺或预期与日记中的观察分开；然后把大结论拆成可检验的小结论，逐项找支持证据和反证；最后用“材料显示、不能确定、有材料反映”等说法限定结论范围，避免把局部材料推广成“所有人都……”。"
}
